window.VisualizationTools.plotly=function(element,json,callback){console.log("!");loadScript('https://cdn.plot.ly/plotly-4.1.1.min.js').then(function(){window.Plotly.newPlot(element,json.data);callback(element,element.childNodes[0])}).catch(function(error){console.error('Could not load Plotly:',error)})}